import { useMemo, useState } from 'react';

function ProductList({ products, query }) {
  const [sortAsc, setSortAsc] = useState(true);
  const [compact, setCompact] = useState(false);

  const visible = useMemo(() => {
    console.log('filtering');
    const filtered = products.filter((p) => p.name.toLowerCase().includes(query.toLowerCase()));
    return filtered.sort((a, b) => (sortAsc ? a.price - b.price : b.price - a.price));
  }, [products, query, sortAsc]);

  return (
    <>
      <button onClick={() => setSortAsc(!sortAsc)}>Sort {sortAsc ? 'ascending' : 'descending'}</button>
      <label>
        <input type="checkbox" checked={compact} onChange={(e) => setCompact(e.target.checked)} />
        Compact
      </label>
      <ul className={compact ? 'compact' : undefined}>
        {visible.map((p) => (
          <li key={p.id}>{p.name} – {p.price}</li>
        ))}
      </ul>
    </>
  );
}

import { memo, useCallback, useState } from 'react';

const Button = memo(function Button({ onClick, children }) {
  console.log('render Button', children);
  return <button onClick={onClick}>{children}</button>;
});

function Toolbar() {
  const [count, setCount] = useState(0);
  const [theme, setTheme] = useState('light');

  const increment = useCallback(() => setCount((c) => c + 1), []);

  return (
    <div className={theme}>
      <p>Count: {count}</p>
      <Button onClick={increment}>Increment</Button>
      <button onClick={() => setTheme((t) => (t === 'light' ? 'dark' : 'light'))}>
        Toggle theme
      </button>
    </div>
  );
}

